static const uint8_t vector_message_add[14u] = {
	0x15, 0x80, 0x04, 0x6C, 0x61, 0x6D, 0x70, 0x06, 0x6F, 0x6E, 0x7C, 0x6F, 0x66, 0x66,
};

static void test_message_add(void **state)
{
	uint8_t     buf[14u];
	situ_msg_t  msg;
	situ_view_t view;

	(void)state;
	memcpy(buf, vector_message_add, sizeof(buf));
	situ_msg_init(&msg, buf, 14u);
	situ_check_eq(fzn_objects_message_view(&msg, 0, 14u, &view), SITU_OK);
	situ_check_eq(fzn_objects_message_validate(view), SITU_OK);

	/* Every value written back through its own setter must reproduce the
	 * bytes it came from. This is what catches a layout change. */
	fzn_objects_message_cmd_set(view, fzn_objects_message_cmd_get(view));
	fzn_objects_message_op_set(&msg, view, fzn_objects_message_op_get(view));
	situ_check_bytes(buf, vector_message_add, sizeof(buf));
}

